// Test 8: Delete functionality
console.log("Test 8: Delete functionality");
const deleteCache = new LRUCache(3);
deleteCache.set('a', 1);
deleteCache.set('b', 2);
deleteCache.set('c', 3);

console.assert(deleteCache.delete('b') === true, "delete('b') should return true when key exists");
console.assert(deleteCache.get('b') === undefined, "get('b') should return undefined after deletion");
console.assert(deleteCache.delete('b') === false, "delete('b') should return false when key doesn't exist");
console.assert(deleteCache.get('a') === 1, "get('a') should still return 1");
console.assert(deleteCache.get('c') === 3, "get('c') should still return 3");

// Test that delete doesn't affect stats
const statsBefore = deleteCache.stats();
deleteCache.delete('a');
const statsAfter = deleteCache.stats();
console.assert(statsBefore.hits === statsAfter.hits, "Delete should not affect hits");
console.assert(statsBefore.misses === statsAfter.misses, "Delete should not affect misses");
console.assert(statsBefore.evictions === statsAfter.evictions, "Delete should not affect evictions");

console.log("✓ Delete functionality works");

// Test 9: Clear functionality
console.log("Test 9: Clear functionality");
const clearCache = new LRUCache(3);
clearCache.set('a', 1);
clearCache.set('b', 2);
clearCache.set('c', 3);

console.assert(clearCache.get('a') === 1, "get('a') should return 1 before clear");
console.assert(clearCache.get('b') === 2, "get('b') should return 2 before clear");
console.assert(clearCache.get('c') === 3, "get('c') should return 3 before clear");

clearCache.clear();

console.assert(clearCache.get('a') === undefined, "get('a') should return undefined after clear");
console.assert(clearCache.get('b') === undefined, "get('b') should return undefined after clear");
console.assert(clearCache.get('c') === undefined, "get('c') should return undefined after clear");

// Test that clear doesn't affect stats
const clearStatsBefore = clearCache.stats();
clearCache.clear();
const clearStatsAfter = clearCache.stats();
console.assert(clearStatsBefore.hits === clearStatsAfter.hits, "Clear should not affect hits");
console.assert(clearStatsBefore.misses === clearStatsAfter.misses, "Clear should not affect misses");
console.assert(clearStatsBefore.evictions === clearStatsAfter.evictions, "Clear should not affect evictions");

console.log("✓ Clear functionality works");

console.log("All tests passed!");

